      b.textContent = b.dataset.rm === "trash" || b.dataset.rm === "vision" ? "Delete?" : b.dataset.rm === "quest" ? "Abandon?" : "Retire?";
      setTimeout(() => { if (b.isConnected) { b.classList.remove("armed"); b.innerHTML = b.dataset.orig; } }, 3500);
